static NSUInteger assertions;
static void Check(BOOL ok,NSString *message) { assertions++;if(!ok){fprintf(stderr,"DOWNLOADS TEST: %s\n",message.UTF8String);exit(3);} }
static void Equal(id a,id b,NSString *message) { Check(a==b||[a isEqual:b],[NSString stringWithFormat:@"%@: %@ versus %@",message,a,b]); }
static NSURL *File(NSString *name) { NSString *path=[DownloadsFixtureRoot stringByAppendingPathComponent:name];Check([path hasPrefix:[DownloadsFixtureRoot stringByAppendingString:@"/"]],@"fixture containment");return [NSURL fileURLWithPath:path]; }
static void Write(NSURL *url,NSData *data) { Check([url.path hasPrefix:[DownloadsFixtureRoot stringByAppendingString:@"/"]],@"write fixture containment");NSError *error=nil;[[NSFileManager defaultManager] createDirectoryAtPath:url.URLByDeletingLastPathComponent.path withIntermediateDirectories:YES attributes:nil error:&error];Check(error==nil,@"create fixture parent");Check([data writeToURL:url atomically:YES],@"write fixture bytes"); }
static NSData *Bytes(NSString *text) { return [text dataUsingEncoding:NSUTF8StringEncoding]; }
static void Remove(NSURL *url) { Check([url.path hasPrefix:[DownloadsFixtureRoot stringByAppendingString:@"/"]],@"remove fixture containment");[[NSFileManager defaultManager] removeItemAtURL:url error:nil]; }
static void Set(id object,NSString *key,id value) { [object setValue:value forKey:key]; }
static id Get(id object,NSString *key) { return [object valueForKey:key]; }
static NSArray *Events(NSString *kind) { @synchronized(DownloadsEvents){NSMutableArray *result=[NSMutableArray array];for(NSDictionary *e in DownloadsEvents)if([e[@"kind"] isEqual:kind])[result addObject:e];return result;} }
static NSDictionary *Last(NSString *kind) { return Events(kind).lastObject; }
static void Pump(BOOL (^condition)(void),NSString *label) { NSDate *limit=[NSDate dateWithTimeIntervalSinceNow:8];while(!condition() && limit.timeIntervalSinceNow>0)[[NSRunLoop currentRunLoop] runUntilDate:[NSDate dateWithTimeIntervalSinceNow:0.002]];Check(condition(),label); }
static DownloadsNode *Format(NSString *mime,NSString *quality,unsigned long long size,int itag) { DownloadsNode *f=[DownloadsNode new];f.mimeType=mime;f.qualityLabel=quality;f.contentLength=size;f.itag=itag;f.URL=@"https://fixture.invalid/media";f.hasContentLength=YES;f.approxDurationMs=12501;return f; }
