    DownloadsNode *player=[DownloadsNode new],*response=[DownloadsNode new],*data=[DownloadsNode new],*stream=[DownloadsNode new],*details=[DownloadsNode new],*active=[DownloadsNode new];
    player.playerResponse=response;response.playerData=data;data.streamingData=stream;data.videoDetails=details;stream.adaptiveFormatsArray=formats;response.videoID=@"video-fixture";details.author=@"Author";details.title=@"Title";player.activeVideo=active;active.availableCaptionTracks=@[];player.contentVideoID=response.videoID;return player;
