static DownloadsNode *Track(NSString *identifier,NSString *name,BOOL defaultAudio) { DownloadsNode *t=[DownloadsNode new];t.id_p=identifier;t.VSSID=identifier;t.displayName=name;t.audioIsDefault=defaultAudio;t.languageCode=@"en";t.URL=File(@"captions-source.xml");t.baseURL=File(@"wrong-selector-must-not-be-used.xml");return t; }
static YTActionSheetAction *Action(NSString *title) { for(YTActionSheetAction *a in DownloadsLastSheet.actions)if([a.title isEqual:title])return a;return nil; }
@interface DownloadsDelegate : NSObject <DownloaderDelegate>
@property(nonatomic,strong) NSURL *url;
@property(nonatomic,strong) NSString *name;
@property(nonatomic,strong) NSError *error;
@property(nonatomic) float progress;
@property(nonatomic) NSUInteger finishes,errors,progressCalls;
@property(nonatomic) BOOL finishMain;
@end
@implementation DownloadsDelegate
- (void)downloadProgress:(float)progress { self.progress=progress;self.progressCalls++; }
- (void)downloadDidFinish:(NSURL *)url fileName:(NSString *)name { self.url=url;self.name=name;self.finishes++;self.finishMain=[NSThread isMainThread]; }
- (void)downloadDidFailureWithError:(NSError *)error { self.error=error;self.errors++; }
@end
