    root.pageStyle=1;DownloadsPreferences[@"oledTheme"]=@NO;UIColor *background=[YTPMedia adaptiveBackgroundColor];DownloadsPreferences[@"oledTheme"]=@YES;CGFloat red=0;[background getRed:&red green:NULL blue:NULL alpha:NULL];Check(fabs(red-0.059)<1e-12,@"background captures preference once");UIColor *oled=[YTPMedia adaptiveBackgroundColor];[oled getRed:&red green:NULL blue:NULL alpha:NULL];Check(red==0,@"OLED dark background");root.pageStyle=0;[oled getRed:&red green:NULL blue:NULL alpha:NULL];Check(red==1,@"dynamic pageStyle update");
