    NSURL *chunk=File(@"downloaded-chunk.bin");Write(chunk,Bytes(@"abcd"));[d URLSession:(id)DownloadsLastSession downloadTask:(id)DownloadsLastSession.tasks.lastObject didFinishDownloadingToURL:chunk];Pump(^BOOL{return session.tasks.count==2;},@"legacy first completion starts next chunk");Equal([[(DownloadsTask *)session.tasks.lastObject originalRequest] valueForHTTPHeaderField:@"Range"],@"bytes=4-7",@"legacy final range not clamped");Write(chunk,Bytes(@"ef"));[d URLSession:(id)DownloadsLastSession downloadTask:(id)DownloadsLastSession.tasks.lastObject didFinishDownloadingToURL:chunk];Pump(^BOOL{return delegate.finishes==1;},@"legacy complete callback");Check(!delegate.finishMain,@"legacy completion global queue");Check(!delegate.url.isFileURL,@"legacy completion plain path URL");Equal([NSData dataWithContentsOfFile:[d getFilePath]],Bytes(@"abcdef"),@"legacy byte concatenation");Equal(delegate.name,@"legacy.bin",@"legacy callback filename");
    Downloader *cancel=[Downloader new];DownloadsDelegate *cd=[DownloadsDelegate new];cancel.delegate=cd;[cancel downloadFileWithURL:requestURL fileName:@"cancel.bin" fileSize:4];DownloadsTask *ct=DownloadsLastSession.tasks.lastObject;[cancel cancelDownload];Check(ct.cancelled&&cd.error.code==NSURLErrorCancelled,@"legacy explicit cancel callback");Check(![[NSFileManager defaultManager]fileExistsAtPath:[cancel getFilePath]],@"legacy cancel removes fixture");NSError *network=[NSError errorWithDomain:@"fixture" code:7 userInfo:nil];[cancel URLSession:(id)DownloadsLastSession task:(id)DownloadsLastSession.tasks.lastObject didCompleteWithError:network];Check(cd.errors==2&&cd.error==network,@"legacy repeated session error forwarding");
