static void TestFFmpeg(void) {
    FFMpegHelper *ff=[FFMpegHelper new];Check([FFMpegHelper sharedInstance]==[FFMpegHelper sharedInstance],@"FFmpeg singleton");NSURL *video=File(@"merge/input.mp4"),*audio=File(@"merge/input.m4a"),*captions=File(@"merge/en.srt"),*thumb=File(@"merge/thumbnail.jpg"),*output=File(@"merge/output.mp4");Write(video,Bytes(@"fixture video"));Write(audio,Bytes(@"fixture audio"));
    for(NSUInteger mask=0;mask<4;mask++){
        if(mask&1)Write(captions,Bytes(@"captions"));else Remove(captions);if(mask&2)Write(thumb,Bytes(@"thumbnail"));else Remove(thumb);
        NSString *command=[ff getCommandWithVideoURL:video audioURL:audio captionsURL:captions thumbnailURL:thumb duration:123 outputURL:output];NSString *expected;
        if(mask==0)expected=[NSString stringWithFormat:@"-hide_banner -loglevel error -i %@ -i %@ -to 123 -c:v copy -c:a copy %@",video,audio,output];
