    @autoreleasepool { @try {
        if(argc!=4){fprintf(stderr,"usage: downloads-runtime REPO FIXTURE_ROOT VECTORS\n");return 64;}
        NSString *repo=@(argv[1]);DownloadsFixtureRoot=@(argv[2]);Check([DownloadsFixtureRoot hasPrefix:[repo stringByAppendingString:@"/.recovery-work/downloads/"]],@"fixture root inside assigned worktree");
        [[NSFileManager defaultManager] createDirectoryAtPath:DownloadsFixtureRoot withIntermediateDirectories:YES attributes:nil error:nil];
        NSDictionary *vectors=[NSJSONSerialization JSONObjectWithData:[NSData dataWithContentsOfFile:@(argv[3])] options:0 error:nil];Check(vectors!=nil,@"independent evidence vectors loaded");
        DownloadsInstallDoubles();NSUInteger metadata=DownloadsAudit(repo);
        TestMedia(vectors);TestTransforms(vectors);TestDownloader(vectors);TestAPI();TestAudio();TestFFmpeg();TestMenus();TestStorageEdges();TestPipelinePreferences();
        printf("Downloads runtime: %lu behavioral assertions + %lu exact ABI assertions = %lu passed.\n",(unsigned long)assertions,(unsigned long)metadata,(unsigned long)(assertions+metadata));return 0;
    } @catch(NSException *exception){fprintf(stderr,"DOWNLOADS UNEXPECTED EXCEPTION: %s\n",exception.description.UTF8String);return 4;} }
